#include <cuda_runtime.h>
#include <vector>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <algorithm>
#include "../ge-spmm-cuda/kernels.h"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int nr=257,nc=263,bc=256,repeat=argc>1?atoi(argv[1]):100;std::vector<int>rp{0},ci;for(int row=0;row<nr;row++){for(int j=0;j<row%65;j++)ci.push_back((row*17+j*19)%nc);rp.push_back(ci.size());}std::vector<float>av(ci.size(),1),b(nc*bc),expected(nr*bc,0),got(nr*bc),output;for(int i=0;i<nc*bc;i++)b[i]=float((i*37+17)%129-64)/64.f;for(int row=0;row<nr;row++)for(int col=0;col<bc;col++)for(int k=rp[row];k<rp[row+1];k++)expected[row*bc+col]+=av[k]*b[ci[k]*bc+col];int *dr,*dc;float *da,*db,*out;CK(cudaMalloc(&dr,rp.size()*4));CK(cudaMalloc(&dc,ci.size()*4));CK(cudaMalloc(&da,av.size()*4));CK(cudaMalloc(&db,b.size()*4));CK(cudaMalloc(&out,got.size()*4));CK(cudaMemcpy(dr,rp.data(),rp.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dc,ci.data(),ci.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(da,av.data(),av.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice));
auto call=[&](int m){dim3 block(32,4),grid((nr+3)/4,(bc+(32<<(m-1))-1)/(32<<(m-1)));if(m==1)spmm_test1<float><<<grid,block,1024>>>(nr,bc,dr,dc,da,db,out);else if(m==2)spmm_test2<float><<<grid,block,1024>>>(nr,bc,dr,dc,da,db,out);else if(m==3)spmm_test3<float><<<grid,block,1024>>>(nr,bc,dr,dc,da,db,out);else spmm_test4<float><<<grid,block,1024>>>(nr,bc,dr,dc,da,db,out);};for(int m=1;m<=4;m++)call(m);CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double times[4]={};bool ok=true;float ma=0,mr=0;output.clear();for(int m=1;m<=4;m++){CK(cudaMemset(out,255,got.size()*4));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)call(m);CK(cudaDeviceSynchronize());times[m-1]=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;CK(cudaMemcpy(got.data(),out,got.size()*4,cudaMemcpyDeviceToHost));for(int i=0;i<got.size();i++){float e=fabsf(got[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(got[i])&&e<=1e-2f;}output.insert(output.end(),got.begin(),got.end());}all&=ok;char file[100];sprintf(file,"ge_spmm_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_four_CSR_SpMM_methods_kernel_regions_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"method_times_seconds\":[%.12g,%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1]+times[2]+times[3],ok?"true":"false",int(output.size()),ma,mr,repeat,times[0],times[1],times[2],times[3],file,int(output.size()));}CK(cudaFree(dr));CK(cudaFree(dc));CK(cudaFree(da));CK(cudaFree(db));CK(cudaFree(out));puts(all?"PASS":"FAIL");return all?0:1;}
